45:   function createDeck(id) {
46:     const audio = $(`#audio-${id}`);
47:     const source = audioContext.createMediaElementSource(audio);
48:     const low = audioContext.createBiquadFilter();
49:     const mid = audioContext.createBiquadFilter();
50:     const high = audioContext.createBiquadFilter();
51:     low.type = 'lowshelf'; low.frequency.value = 100;
52:     mid.type = 'peaking'; mid.frequency.value = 2500; mid.Q.value = 0.8;
53:     high.type = 'highshelf'; high.frequency.value = 12000;
54:     const volume = audioContext.createGain();
55:     const cross = audioContext.createGain();
56:     const analyser = audioContext.createAnalyser();
57:     analyser.fftSize = 1024;
58:     analyser.smoothingTimeConstant = 0.82;
59:     source.connect(low).connect(mid).connect(high).connect(volume).connect(cross).connect(analyser).connect(audioContext.destination);
60:     decks[id] = {
61:       id, audio, source, filters: { low, mid, high }, volume, cross, analyser,
62:       data: new Uint8Array(analyser.frequencyBinCount), bpm: id === 'a' ? 120 : 124,
63:       baseBpm: id === 'a' ? 120 : 124, pitch: 0, objectUrl: null, trackName: '', artist: '',
64:       demo: false, cuePoint: 0, lastPhase: 0
65:     };
