215:   function cueDeck(id) {
216:     const deck = decks[id];
217:     if (!deck?.audio.src) { toast('Carga una pista antes de marcar CUE.'); return; }
218:     deck.audio.pause();
219:     deck.audio.currentTime = deck.cuePoint;
220:     updateTransport(id);
221:   }
