364:   function loadLibraryTrack(track, id) {
365:     if (track.kind === 'demo') {
366:       startDemo(id);
367:       return;
368:     }
369:     const picker = document.createElement('input'); picker.type = 'file'; picker.accept = 'audio/*';
370:     picker.addEventListener('change', () => {
371:       const file = picker.files?.[0];
372:       if (file) loadLocalFile(file, id);
373:     }, { once: true });
374:     picker.click();
375:     toast('Vuelve a elegir el archivo: el navegador no guarda el audio en la biblioteca.');
376:   }
