378:   function loadLocalFile(file, id) {
379:     if (!file.type.startsWith('audio/')) { toast('Elige un archivo de audio compatible.'); return; }
380:     const url = URL.createObjectURL(file);
381:     attachTrack(id, url, { name: file.name.replace(/\.[^.]+$/, ''), artist: 'Archivo local · solo este dispositivo', duration: 0, bpm: id === 'a' ? 120 : 124, demo: false, loop: false });
382:     const deck = decks[id];
383:     deck.audio.onloadedmetadata = () => {
384:       const entry = library.find(item => item.name === deck.trackName && item.source === 'Local');
385:       if (entry) { entry.duration = deck.audio.duration || 0; persistLibrary(); renderLibrary(); }
386:     };
387:     toast(`Audio local cargado en Deck ${id.toUpperCase()}`);
388:   }
