390:   function addPlaylistFiles(files) {
391:     const audioFiles = [...files].filter(file => file.type.startsWith('audio/'));
392:     if (!audioFiles.length) { toast('Elige uno o más archivos de audio compatibles.'); return; }
393:     mixPlaylist.push(...audioFiles);
394:     renderMixPlaylist();
395:     toast(`${audioFiles.length} ${audioFiles.length === 1 ? 'pista añadida' : 'pistas añadidas'} a tu playlist`);
