398:   function renderMixPlaylist() {
399:     const list = $('#mix-playlist');
400:     if (!mixPlaylist.length) {
401:       const empty = document.createElement('li');
402:       empty.className = 'playlist-empty';
403:       empty.textContent = 'Aún no hay pistas. Añade archivos de audio para empezar a mezclar.';
404:       list.replaceChildren(empty);
405:       return;
406:     }
407:     list.replaceChildren(...mixPlaylist.map((file, index) => {
408:       const item = document.createElement('li');
409:       item.className = 'mix-playlist-item';
410:       const name = document.createElement('span');
411:       name.className = 'mix-playlist-name';
412:       name.textContent = file.name;
413:       const actions = document.createElement('span');
414:       actions.className = 'mix-playlist-actions';
415:       for (const id of ['a', 'b']) {
416:         const button = document.createElement('button');
417:         button.type = 'button';
418:         button.className = 'table-load';
419:         button.textContent = id.toUpperCase();
420:         button.setAttribute('aria-label', `Cargar ${file.name} en Deck ${id.toUpperCase()}`);
421:         button.addEventListener('click', () => loadLocalFile(file, id));
422:         actions.append(button);
423:       }
424:       item.append(name, actions);
