292:   function updatePhase() {
293:     if (!decks.a || !decks.b) return;
294:     const a = decks.a, b = decks.b;
295:     const beatsA = a.audio.currentTime * a.bpm / 60;
296:     const beatsB = b.audio.currentTime * b.bpm / 60;
297:     const phaseA = ((beatsA % 1) + 1) % 1;
298:     const phaseB = ((beatsB % 1) + 1) % 1;
299:     let delta = Math.abs(phaseA - phaseB) * 60000 / Math.max(a.bpm, 1);
300:     delta = Math.min(delta, 60000 / Math.max(a.bpm, 1) - delta);
301:     $('#phase-readout').textContent = a.audio.src && b.audio.src ? `FASE ${Math.round(delta)} MS` : 'FASE —';
302:   }
