331:       if (samples[i].energy > threshold && samples[i].energy >= samples[i - 1].energy && samples[i].energy > samples[i + 1].energy && samples[i].time - (peaks.at(-1)?.time || -Infinity) > 0.22) peaks.push(samples[i]);
